mapper.select:
select region_seq
	from tbl_expert_region
		where expert_seq = #{expertSeq}

select latitude as base_lat, longitude as base_lng, address
	from tbl_member
		where member_seq = #{memberSeq}

select * from ( select e.expert_seq, m.name, e.intro, e.service_address, e.service_latitude, e.service_longitude, nvl(rv.review_count, 0) as review_count, nvl(rv.avg_rating, 0) as avg_rating, nvl(tr.hire_count, 0) as hire_count, to_char(m.last_login_date, 'YYYY-MM-DD HH24:MI') as last_login_date, tl.title as talent_title, tl.price, as distance_km
)
distance_km <= #{radiusKm}
order by
review_count desc, expert_seq avg_rating desc, review_count desc, expert_seq last_login_date desc nulls last, expert_seq hire_count desc, expert_seq distance_km nulls last, expert_seq
offset #{offset} rows fetch next #{size} rows only

select count(*)
	from (
		select e.expert_seq,
				 as distance_km

	)


		distance_km <= #{radiusKm}
